import{_ as n,C as s,o,c as l,j as i,E as r,a as d,a3 as e}from"./chunks/framework.C6R8kWFE.js";const v=JSON.parse(`{"title":"5-hafta","description":"","frontmatter":{"title":"5-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"8-sinf (Foundation)","link":"/8-sinf-cs/"},"n":5,"bob":"II-bob · Zamonaviy IT yo‘nalishlari va raqamli infratuzilma asoslari","lessons":[{"g":13,"title":"Bulutli xizmatlar va onlayn hamkorlik vositalari (3-qism): sinxronlash, xavfsizlik va mini-loyiha","lead":"Telefonda olgan rasmingiz bir zumda kompyuterda paydo bo'ladi, do'stingiz bilan bitta taqdimotni bir vaqtda yozasiz. Bugun buning qanday ishlashini, ma'lumotlaringizni bulutda qanday himoya qilishni bilib olasiz va jamoa bo'lib birinchi «bulutdagi loyiha»ni bajarasiz.","link":"/8-sinf-cs/hafta-05/dars-1","slide":"/slaydlar/8-sinf-cs/hafta-05/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-05/dars-1-test.html"},{"g":14,"title":"Git va GitHub bilan tanishuv (1-qism): versiya nazorati, repository va commit","lead":"referat_oxirgi.docx, referat_oxirgi_ROSTDAN_v3.docx... Qaysi biri to'g'ri? Dasturchilar bu muammoni ancha oldin hal qilgan: ular har bir o'zgarishni «saqlash nuqtasi» sifatida yozib boradi. Bugun bu tizim — Git va uning bulutdagi uyi — GitHub bilan tanishasiz.","link":"/8-sinf-cs/hafta-05/dars-2","slide":"/slaydlar/8-sinf-cs/hafta-05/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-05/dars-2-test.html"},{"g":15,"title":"Git va GitHub bilan tanishuv (2-qism): kompyuterda Git — init, status, add, commit, log","lead":"O'tgan darsda commitni sayt orqali qildingiz. Haqiqiy dasturchilar esa o'z kompyuterida, terminalda ishlaydi — internetsiz ham. Bugun beshta buyruq bilan o'z «kundalik» repository'ingizni yaratasiz va uning tarixini ko'rasiz.","link":"/8-sinf-cs/hafta-05/dars-3","slide":"/slaydlar/8-sinf-cs/hafta-05/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-05/dars-3-test.html"}],"test":"/slaydlar/8-sinf-cs/hafta-05/hafta-test.html"}},"headers":[],"relativePath":"8-sinf-cs/hafta-05/index.md","filePath":"8-sinf-cs/hafta-05/index.md"}`),u={name:"8-sinf-cs/hafta-05/index.md"},m={class:"blk"},h={id:"uyga-vazifa",tabindex:"-1"};function g(c,a,b,f,y,q){const t=s("Icon");return o(),l("div",null,[i("div",m,[i("h2",h,[r(t,{name:"house"}),a[0]||(a[0]=d(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=e('<p>Har bir vazifa 20–30 daqiqa vaqt oladi. Vazifalar daftarda yoki kompyuterda alohida papkada saqlanadi. Akkaunt kerak bo&#39;lgan qadamlarni ota-onangiz ruxsati va yordami bilan bajaring; akkaunt yoki Git bo&#39;lmasa, shu qadamni daftarda chizma, jadval yoki «commit kartochkalari» ko&#39;rinishida bajaring.</p><h3 id="_13-dars-uchun-bulutli-xizmatlar-3-qism" tabindex="-1">13-dars uchun (Bulutli xizmatlar, 3-qism) <a class="header-anchor" href="#_13-dars-uchun-bulutli-xizmatlar-3-qism" aria-label="Permalink to &quot;13-dars uchun (Bulutli xizmatlar, 3-qism)&quot;">​</a></h3><p><strong>1-topshiriq: «Mening bulutim xavfsizmi?»</strong></p><ol><li>O&#39;zingizning (yoki ota-onangiz bilan tanlangan namunaviy) 3 ta bulutdagi faylingiz uchun ruxsatlar auditi jadvalini tuzing: fayl, kim kira oladi, qanday ruxsat, o&#39;zgartirish kerakmi.</li><li>Kamida bitta keraksiz ruxsatni olib tashlang yoki «Havolasi bor har kim» ni <strong>Cheklangan</strong> ga o&#39;zgartiring (yoki daftarda qanday qilishni yozing).</li><li>Bulutdagi xotirangiz qancha band ekanini toping va joyni bo&#39;shatishning 3 qadamli rejasini yozing.</li><li>Bulutda xavfsizlikning 5 qoidasidan oilangiz uchun «eslatma varaqasi» tayyorlang.</li></ol><p><strong>Kutiladigan natija:</strong> 3 qatorli audit jadvali, kamida 1 ta tuzatilgan ruxsat, xotira rejasi va 5 bandli eslatma.</p><h3 id="_14-dars-uchun-git-va-github-1-qism" tabindex="-1">14-dars uchun (Git va GitHub, 1-qism) <a class="header-anchor" href="#_14-dars-uchun-git-va-github-1-qism" aria-label="Permalink to &quot;14-dars uchun (Git va GitHub, 1-qism)&quot;">​</a></h3><p><strong>2-topshiriq: «Men haqimda» repository&#39;si</strong></p><ol><li>GitHub&#39;da <code>men-haqimda</code> nomli repository&#39;ni <strong>Add a README file</strong> bilan yarating.</li><li>README&#39;ni Markdown&#39;da to&#39;ldiring: <code>#</code> sarlavha, <code>##</code> «Qiziqishlarim» bo&#39;limi, <strong>qalin</strong> matn va kamida 3 bandli ro&#39;yxat. Telefon raqami va manzil yozmang!</li><li>Kamida <strong>3 ta commit</strong> qiling, har biriga tushunarli xabar yozing.</li><li>Commits sahifasidan har commitning xabari, vaqti va qisqa ID&#39;sini daftarga yozing.</li></ol><p><strong>Kutiladigan natija:</strong> repository havolasi, formatlangan README va 3 ta commit jadvali.</p><h3 id="_15-dars-uchun-git-va-github-2-qism" tabindex="-1">15-dars uchun (Git va GitHub, 2-qism) <a class="header-anchor" href="#_15-dars-uchun-git-va-github-2-qism" aria-label="Permalink to &quot;15-dars uchun (Git va GitHub, 2-qism)&quot;">​</a></h3><p><strong>3-topshiriq: «Kundalik» davomi</strong></p><ol><li>Darsdagi <code>kundalik</code> repository&#39;sida har kun uchun bitta fayl yarating (<code>seshanba.txt</code>, <code>chorshanba.txt</code>, ...) — kamida 3 ta yangi fayl.</li><li>Har bir faylni alohida commit qiling (<code>git add</code> → <code>git commit -m &quot;...&quot;</code>), har safar oldin va keyin <code>git status</code> ni tekshiring.</li><li><code>README.md</code> ga «Bu hafta nimani o&#39;rgandim» bo&#39;limini qo&#39;shib, commit qiling.</li><li><code>git log --oneline</code> natijasining skrinshotini oling yoki daftarga ko&#39;chiring (kamida 6 ta commit).</li></ol><p><strong>Kutiladigan natija:</strong> kamida 6 ta commitli tarix va har bir commit uchun aniq xabar.</p>',13))])])}const z=n(u,[["render",g]]);export{v as __pageData,z as default};
